from vllm.core.block.prefix_caching_block import PrefixCachingBlockAllocator

# Test get_common_computed_block_ids with various edge cases
allocator = PrefixCachingBlockAllocator(num_blocks=256, block_size=16)

test_cases = [
    # Basic cases
    {
        "input": [[1, 2, 3], [1, 2, 4], [1, 2, 5]],
        "expected": [1, 2],
        "description": "Common prefix with different endings"
    },
    {
        "input": [[1, 2, 3], [1, 2, 3], [1, 2, 3]],
        "expected": [1, 2, 3],
        "description": "All lists identical"
    },
    {
        "input": [[1, 2, 3], [4, 5, 6]],
        "expected": [],
        "description": "No common prefix"
    },
    {
        "input": [[1], [1, 2, 3]],
        "expected": [1],
        "description": "First list shorter"
    },
    {
        "input": [[1, 2, 3], []],
        "expected": [1, 2, 3],
        "description": "One empty list"
    },
    {
        "input": [[]],
        "expected": [],
        "description": "Single empty list"
    },
    {
        "input": [[], []],
        "expected": [],
        "description": "Multiple empty lists"
    },
    {
        "input": [[1, 2, 3], [1, 2, 3], [1, 2, 4]],
        "expected": [1, 2],
        "description": "Two identical, one different"
    },
    # Edge cases with larger lists
    {
        "input": [[i for i in range(100)], [i for i in range(100)], [i for i in range(100)]],
        "expected": [i for i in range(100)],
        "description": "Large identical lists"
    },
    {
        "input": [[i for i in range(100)], [i for i in range(99)], [i for i in range(98)]],
        "expected": [i for i in range(98)],
        "description": "Large lists with different lengths"
    },
    {
        "input": [[i for i in range(100)], [i for i in range(100)] + [100], [i for i in range(100)]],
        "expected": [i for i in range(100)],
        "description": "Large lists with one longer"
    },
    # Single list
    {
        "input": [[1, 2, 3]],
        "expected": [1, 2, 3],
        "description": "Single list"
    },
    {
        "input": [[]],
        "expected": [],
        "description": "Single empty list"
    },
]

all_passed = True
for i, test_case in enumerate(test_cases):
    result = allocator.get_common_computed_block_ids(test_case["input"])
    expected = test_case["expected"]

    if result != expected:
        print(f"FAILED Test {i+1}: {test_case['description']}")
        print(f"  Input: {test_case['input']}")
        print(f"  Expected: {expected}")
        print(f"  Got: {result}")
        all_passed = False
    else:
        print(f"PASSED Test {i+1}: {test_case['description']}")

if all_passed:
    print("\nAll tests passed!")
else:
    print("\nSome tests failed!")
    exit(1)

